      run_as_user: 'agent',
      projects_root: tmpdir(),
      dashboard: {
        bind: '127.0.0.1',
        port: 8080,
      },
      data_dir: dataDir,
      ssh_hint: 'test@host',
    },
    session: {
      max_goals: 3,
      max_turns: 10,
      max_turns_per_seat: {
        pm: 5,
        dev: 6,
        qc: 4,
        audit: 4,
      },
      require_task_approval: false,
      auto_schedule: false,
    },
    turn: {
      timeout_minutes: {
        pm: 10,
        dev: 25,
        qc: 20,
        audit: 20,
      },
      max_parallel_agents: 1,
      commit_before_dev_turn: true,
      max_fix_rounds: 2,
    },
    seats: {
      pm: 'elon',
      dev: 'jacky',
      qc: 'jenny',
      audit: opts?.auditSeat ?? '',
    },
    agents: {
      elon: { tool: 'claude-code', command: 'claude', can_sit: ['pm'] },
      jacky: { tool: 'antigravity-cli', command: 'agy', can_sit: ['dev'] },
      jenny: { tool: 'claude-code', command: 'claude', can_sit: ['qc'] },
